# ========== CLIENTE REAL DE DEEPSEEK ==========

class DeepSeekClient:
    """Cliente optimizado para DeepSeek con manejo de errores y reintentos"""

    def __init__(self, api_key: str = None, model: str = "deepseek-chat"):
        self.api_key = api_key or os.getenv("DEEPSEEK_API_KEY")
        self.model = model
        self.max_retries = 3
        self.retry_delay = 1
        self.call_history = []

    def chat(self, prompt: str, system_prompt: str = None,
             temperature: float = 0.7, max_tokens: int = 2000) -> Dict:
        messages = []
        if system_prompt:
            messages.append({"role": "system", "content": system_prompt})
        messages.append({"role": "user", "content": prompt})

        payload = {
            "model": self.model,
            "messages": messages,
            "temperature": temperature,
            "max_tokens": max_tokens
        }

        for attempt in range(self.max_retries):
            try:
                response = self._call_api(payload)

                self.call_history.append({
                    'timestamp': datetime.now().isoformat(),
                    'prompt_length': len(prompt),
                    'response_length': len(response.get('content', '')),
                    'tokens_used': response.get('usage', {}).get('total_tokens', 0),
                    'success': True
                })

                return {
                    'success': True,
                    'content': response['choices'][0]['message']['content'],
                    'tokens': response.get('usage', {}),
                    'model': self.model
                }

            except Exception as e:
                print(f"  ⚠️ Intento {attempt + 1} fallido: {str(e)[:100]}")

                if attempt < self.max_retries - 1:
                    time.sleep(self.retry_delay * (attempt + 1))
                else:
                    self.call_history.append({
                        'timestamp': datetime.now().isoformat(),
                        'error': str(e),
                        'success': False
                    })

                    return {
                        'success': False,
                        'content': f"Error después de {self.max_retries} intentos: {str(e)[:200]}",
                        'error': str(e)
                    }

    def _call_api(self, payload: Dict) -> Dict:
        try:
            import requests
            response = requests.post(
                "https://api.deepseek.com/v1/chat/completions",
                headers={
                    "Authorization": f"Bearer {self.api_key}",
                    "Content-Type": "application/json"
                },
                json=payload,
                timeout=30
            )
            response.raise_for_status()
            return response.json()

        except ImportError:
            curl_cmd = [
                'curl', '-s', '-X', 'POST',
                'https://api.deepseek.com/v1/chat/completions',
                '-H', f'Authorization: Bearer {self.api_key}',
                '-H', 'Content-Type: application/json',
                '-d', json.dumps(payload)
            ]
            result = subprocess.run(curl_cmd, capture_output=True, text=True)
            return json.loads(result.stdout)

